args.sparql:
SELECT DISTINCT ?father ?fatherLabel WHERE {
  <http://dbpedia.org/resource/Sancho_Ram%C3%ADrez> ?p ?father .
  ?father rdfs:label ?fatherLabel .
  FILTER(langMatches(lang(?fatherLabel), "en") )
  FILTER(CONTAINS(LCASE(STR(?fatherLabel)), "ramiro"))
} LIMIT 50

